    using System;
using System.Collections.Generic;

class MinHeap {
    private List<int> heap = new List<int>();

    public int Count => heap.Count;

    public int Peek() {
        if (heap.Count == 0)
            throw new InvalidOperationException();
        return heap[0];
    }

    public void Push(int val) {
        heap.Add(val);
        HeapifyUp(heap.Count - 1);
    }

    public int Pop() {
        if (heap.Count == 0)
            throw new InvalidOperationException();
        int top = heap[0];
        heap[0] = heap[heap.Count - 1];
        heap.RemoveAt(heap.Count - 1);
        if (heap.Count > 0)
            HeapifyDown(0);
        return top;
    }

    private void HeapifyUp(int idx) {
        while (idx > 0) {
            int parent = (idx - 1) / 2;
            if (heap[parent] <= heap[idx])
                break;
            Swap(parent, idx);
            idx = parent;
        }
    }

    private void HeapifyDown(int idx) {
        int n = heap.Count;
        while (true) {
            int left = 2 * idx + 1;
            int right = 2 * idx + 2;
            int smallest = idx;

            if (left < n && heap[left] < heap[smallest])
                smallest = left;
            if (right < n && heap[right] < heap[smallest])
                smallest = right;

            if (smallest == idx)
                break;

            Swap(idx, smallest);
            idx = smallest;
        }
    }

    private void Swap(int i, int j) {
        int temp = heap[i];
        heap[i] = heap[j];
        heap[j] = temp;
    }
}

class GfG {
    static List<int> jobSequencing(int[] deadline, int[] profit) {
        int n = deadline.Length;
        var jobs = new List<(int d, int p)>();
        for (int i = 0; i < n; i++)
            jobs.Add((deadline[i], profit[i]));

        // sort jobs by deadline
        jobs.Sort((a, b) => a.d.CompareTo(b.d));

        var minHeap = new MinHeap();

        foreach (var job in jobs) {
            // if job can be scheduled within its deadline
            if (minHeap.Count < job.d) {
                minHeap.Push(job.p);
            }
            // replace the job with the lowest profit
            else if (minHeap.Count > 0 && minHeap.Peek() < job.p) {
                minHeap.Pop();
                minHeap.Push(job.p);
            }
        }

        int totalJobs = minHeap.Count;
        int totalProfit = 0;
        while (minHeap.Count > 0) {
            totalProfit += minHeap.Pop();
        }

        return new List<int> { totalJobs, totalProfit };
    }

    public static void Main() {
        int[] deadline = { 2, 1, 2, 1, 1 };
        int[] profit = { 100, 19, 27, 25, 15 };
        List<int> ans = jobSequencing(deadline, profit);
        Console.WriteLine(ans[0] + " " + ans[1]);
    }
}


